-- Tareas de investigación: la lista de qué buscar (FamilySearch, Registro Civil, datos por cargar),
-- ordenada por lo que más desbloquea. Se muestra arriba en Tareas, con casillas para tachar.
create table if not exists research_tasks (
  id uuid primary key default gen_random_uuid(),
  tree_id uuid not null references trees(id) on delete cascade,
  group_rank int not null,
  group_label text not null,
  group_unlocks text not null default '',
  item_rank int not null,
  title text not null,
  detail text not null default '',
  links jsonb not null default '[]'::jsonb,
  done boolean not null default false,
  done_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists research_tasks_tree_idx on research_tasks (tree_id, group_rank, item_rank);
alter table research_tasks enable row level security;

insert into research_tasks (tree_id, group_rank, group_label, group_unlocks, item_rank, title, detail, links)
select (select id from trees order by created_at limit 1), g.gi, g.grp->>0, g.grp->>1, i.ii, i.it->>0, i.it->>1,
       coalesce((select jsonb_agg(jsonb_build_object('label', c, 'url', 'https://www.familysearch.org/ark:/61903/1:1:' || c))
                 from jsonb_array_elements_text(i.it->2) c), '[]'::jsonb)
from jsonb_array_elements($j$[["Daniel Zamora y Carmen Zamora Lobos", "Desbloquea ~37 personas: toda la rama hoy marcada como teoría", [["Bautizo de Daniel, 13 dic 1862 (San Esteban)", "¿Nombra al padre? ¿Dice «hijo natural»? Padrinos (a menudo son parientes). Si nombra a Carmen como madre, la teoría pasa a confirmada.", ["FJ5H-HBH", "6DHN-QZSZ"]], ["Matrimonio de Daniel con Natividad Galdames, 1881 (San Esteban)", "Padres de Daniel, edades y testigos.", []]]], ["Ruz–Martínez (María Martínez Ruz y Juan de Dios Ruz Ibarra)", "Desbloquea a Fermín Ruz, Juana Ibarra, Juan Martínez y Francisca Ruz, y sus ascendientes", [["Matrimonio parroquial de Juan de Dios Ruz, 19 ago 1890", "Edad real (las fuentes dan 42, 50 y 65), viudez, dispensa de consanguinidad (explica el parentesco Ruz–Martínez), padres Fermín Ruz y Juana Ibarra (¿«Glara»?).", ["X4W9-WFCJ"]], ["Matrimonio de Juan Isidro Martínez Ruz, 28 sep 1885", "Revisar sus padres; nació en «Pelasco»/Molina.", ["XS66-PL19"]], ["Juana Ibarra Ibarra, esposa de Fermín Ruy", "Confirmar que es la madre de Juan de Dios.", ["XS6D-WLXP"]], ["Registro de Teno: ¿López o Ruz?", "", ["6DHN-XW2C"]], ["Libros parroquiales de Molina y primer matrimonio de Juan de Dios", "", []]]], ["Rosa Elvira Canelo y José Dolores Canelo", "Abre Canelo, Duarte y Frez (José Canelo, Josefa Duarte, Digna Frez Carvallo)", [["Bautizo de Rosa Elvira, 1896: ¿quién es su madre?", "El índice nombra a Petronila Montesino; ¿Digna Frez/Fredes o madre no declarada?", ["6ZT5-Q6HZ"]], ["Bautizo en Panquehue de María Elena, 1912", "Madre «Elvira Canelo»: ¿hija de Rosa Elvira? ¿Gregoria Zamora es parienta de Manuel?", ["689X-JFZN", "689X-KPQ1"]], ["Matrimonio de Manuel Zamora y Rosa Elvira (~1915)", "Índices de San Esteban (1885–1932), Panquehue (1901–1932) y Santa Rosa de Los Andes. Santa María ya revisado sin resultado.", []], ["José Dolores Canelo: defunción y rastro después de 1906", "Imágenes de la sepultura de Luis (1906) y ¿«viuda de Canelo»?; ¿Petronila se casó con Ismael Figueroa (hijos Figueroa Montesino, 1910 y 1915)?; sepulturas de Viña del Mar 1906–1930.", ["6X4J-W4WJ", "6DSF-QXBB"]]]], ["Natividad Galdames Mandiola: ¿padre Galdames o Espinosa?", "Abre la línea Galdames/Mandiola", [["Juan Galdamez: matrimonio de Marcelino 1875 y bautizo 1851", "¿Dice «finado»? ¿Galdames o Espinosa?", ["FV91-228", "FJRQ-LBM"]], ["María Mandiola: defunción 1898 y bautizo de Natividad Espinosa 1859", "Padres y padrinos.", ["QVM2-N93S", "FJ2F-TMY"]], ["Imágenes sin indexar de San Felipe y San Esteban, 1830–1860", "Matrimonio de Juan Galdames con Santos Mandiola.", []], ["Geneanet: árboles luisnieto, antonio2012 y matrix34", "¿Citan el acta del matrimonio de Roque Galdames y Ana Agustina (2 nov 1664)? ¿Putaendo o Santa Rosa de Los Andes?", []]]], ["Balcázar, Araya y González", "Frontera: Gregorio Balcázar y Dominga Bravo; Belisario Araya y Pabla Zuñiga; Bruno González y Manuela Uribe", [["Isidoro Balcázar: matrimonio 5 mar 1849", "Padres de ambos (de Pabla solo figura Anastacia), edades, testigos.", []], ["Francisco González Uribe: matrimonio 23 jul 1878 y nacimiento 16 sep 1855", "Padres, edades, lugar de nacimiento, testigos; ¿es el bautizo? padrinos.", []], ["Juan Balcázar Araya: sepultura 28 ago 1913", "Ver si dice dónde está sepultado.", []]]], ["Barroso y Farías", "Abre a Germán Barroso y la madre de Juan Bautista Farías", [["Juana del Carmen Barroso Ruz: defunción 2008", "Debería traer a sus padres (Registro Civil).", []], ["Juan Bautista Farías: información matrimonial 1927 (Santa Ana, n.º 138)", "Madre Aniceta Ramírez y la calle del primer testigo.", []]]], ["Línea colonial", "Confirmaciones de bajo costo", [["Árbol de FamilySearch: L5F6-97B, MVGP-VB9, LH14-G53, LH14-GY6", "Padres de Santos Mendiola, Andrés Lobo y Ventura Navarrete.", []], ["Andrés Lobo: bautizo 30 nov 1781", "¿Es realmente hijo de Isabel?", []], ["José Antonio Zamora, c. 1760", "Muerte y nacimiento; «bautismo sin fecha»: ¿es el suyo?", []], ["Marta Brito, c. 1769", "Fecha estimada; buscar defunción y padres.", []], ["Pedro Quintero: matrimonio 13 jul 1846", "¿De verdad el apellido es Marchán?", []]]], ["Datos sueltos", "Cierran un detalle, no abren ramas", [["Manuel Eulogio Zamora Lobo: defunción 6 abr 1844", "De qué murió.", []], ["Familia Canelo en Viña del Mar", "Documentos originales de Eduardo de la Cruz (n. 1903, † 1980) y María Canelo Canelo (n. 1908, † 1973): ¿nombran al padre? Enrique Canelo (n. 7 jun 1900) sin sepultura.", ["8CDW-6N2M", "Z4NQ-G9ZM"]], ["Hijas Juana (1891 y 1892) y Luzana del Carmen (1872)", "Sin defunción: ver si murieron niñas.", []], ["Hermanos de Manuel Zamora Galdames", "Preguntar a la familia; defunciones de Daniel y Natividad (post-1933 no indexado).", []]]], ["Registro Civil (fuera de FamilySearch)", "Online piden RUN; para nacidos antes de 1900 pedir búsqueda por nombre en oficina o al 600 370 2000, con circunscripción, año y número", [["Nacimiento de Ana Rosa Zamora Canelo (3 sep 1921)", "Nombra a los padres, edades y lugar de nacimiento de la madre.", []], ["Matrimonio de Manuel y Rosa Elvira (~1915)", "", []], ["Defunciones de Rosa Elvira (19 oct 1975) y Manuel (1967)", "Nombran a sus padres.", []]]], ["Datos ya encontrados: falta cargarlos en la app", "Trabajo mío, no tuyo", [["Juan Manuel Canelo: defunción 26 may 1893 y sepultura 27 may 1893 (Viña del Mar)", "", []], ["Roque Galdames: matrimonio 2 nov 1664 (fuente secundaria, Geneanet)", "Solo si lo apruebas.", []], ["Hijos de Daniel y Natividad: Enrique (n. 10 oct 1895) y María «Zenobia» (bautizada 6 sep 1899)", "Revisar si ya quedaron cargados.", []], ["Scripts de carga sin correr", "ordenar-jose-dolores.ts y cargar-zamora-4 a 12: comprobar cuáles ya se aplicaron.", []]]], ["Cuidado con homónimos", "Para no confundirse al buscar", [["«Dolores Canelo» sepultados en 1904, 1911, 1912 y 1917", "Aparecen como mujeres: no son José Dolores.", []], ["«Santos Mandiola» muerta en Los Andes en 1887", "No es la madre de Natividad (ella murió el 19 jul 1898 en San Esteban).", []], ["Carmen Zamora Lobos muerta en 1873 (Cabildo)", "Es otra Carmen soltera: nuestra Carmen tuvo hijos hasta 1880.", []]]]]$j$::jsonb) with ordinality as g(grp, gi)
cross join lateral jsonb_array_elements(g.grp->2) with ordinality as i(it, ii)
where not exists (select 1 from research_tasks);
